changeSet.sql:
INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'notification.form058-affiliated-received.enabled', 'true', 'BOOLEAN', 'Notify every organization affiliated with the patient (workplace/place of study, excluding sender/receiver) when a Form058 is created.', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'notification.form058-affiliated-received.enabled');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'notification.form058-affiliated-card-linked.enabled', 'true', 'BOOLEAN', 'Notify every organization affiliated with the patient (workplace/place of study, excluding sender/receiver) when a Form058 reaches CARD_LINKED, so they know they can attach an Act.', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'notification.form058-affiliated-card-linked.enabled');

rollback.sql:
DELETE FROM system_settings WHERE setting_key IN (
    'notification.form058-affiliated-received.enabled',
    'notification.form058-affiliated-card-linked.enabled'
);
